-- Optional company mark printed in the issuer box of the DANFE (NF-e model 55)
-- generated by Nexus (NT 2026.010 portrait and landscape layouts).
-- Kept apart from the DANFSe logo: the DANFE slot is 3.20 cm x 2.20 cm, the
-- DANFSe header is 4.00 cm x 1.16 cm.

alter table organization_companies
    add column if not exists danfe_custom_logo_enabled boolean not null default false,
    add column if not exists danfe_logo bytea,
    add column if not exists danfe_logo_content_type text,
    add column if not exists danfe_logo_print bytea,
    add column if not exists danfe_logo_print_content_type text;

comment on column organization_companies.danfe_custom_logo_enabled is
    'When true and danfe_logo_print (or danfe_logo) is set, the generated DANFE prints the company mark in the issuer box.';

comment on column organization_companies.danfe_logo is
    'Original PNG or JPEG uploaded for the DANFE. Not drawn on the PDF.';

comment on column organization_companies.danfe_logo_print is
    'PNG fitted inside the DANFE issuer box (3.20 cm x 2.20 cm at 300 DPI). Drawn on the PDF when the custom logo flag is on.';
